for (let i = 0; i < n; i++) {
  const a = BigInt(input[pos++]);
  const b = BigInt(input[pos++]);
  lines.push({
    id: i,
    a,
    y1: a * x1 + b,
    y2: a * x2 + b
  });
}

const order1 = lines.slice().sort((u, v) => {
  if (u.y1 < v.y1) return -1;
  if (u.y1 > v.y1) return 1;
  if (u.a > v.a) return -1;
  if (u.a < v.a) return 1;
  return 0;
});

const order2 = lines.slice().sort((u, v) => {
  if (u.y2 < v.y2) return -1;
  if (u.y2 > v.y2) return 1;
  if (u.a < v.a) return -1;
  if (u.a > v.a) return 1;
  return 0;
});

const rank = new Array(n);
for (let i = 0; i < n; i++) {
  rank[order2[i].id] = i;
}

const bit = new Int32Array(n + 1);
function add(index) {
  for (let i = index + 1; i <= n; i += i & -i) bit[i]++;
}
function sum(count) {
  let result = 0;
  for (let i = count; i > 0; i -= i & -i) result += bit[i];
  return result;
}

let answer = 0;
for (let i = 0; i < n; i++) {
  const r = rank[order1[i].id];
  answer += i - sum(r + 1);
  add(r);
}

console.log(answer.toString());
